.container-buscar {
    font-size: 9px;
    height: 450px;
    background: transparent url(../../images/logo/Hasteamento-da-Bandeira-de-Rondonia-no-Trevo-do-Roque.png) 0% 0% no-repeat padding-box;
    opacity: 1;
    background-position: center center;
    background-size: cover;
    padding-top: 180px !important;
}

@media only screen and (max-width: 990px) {
    .container-buscar {
        font-size: 7px;
    }
}

@media only screen and (max-width: 600px) {
    .container-buscar {
        padding-top: 170px !important;
        font-size: 7px;
        height: 400px;
    }
}

/* busca home */
#busca .label-busca {
    font-weight: normal;
    font-size: 3.517em;
    color: #FFF;
    margin: 0;
    line-height: 1.2;
}

#home.usuario-anonimo #busca .label-busca {
    font-size: 4.333em
}

#busca .input-busca {
    display: block;
    background: none;
    border-radius: 29px;
    height: 57px;
    position: relative;
    margin-top: 25px;
    border: 2px solid #FFF;
}

#busca .input-busca #input-procura {
    font-size: 2.1em;
    border: none;
    height: 57px;
    line-height: 50%;
    color: #FFF;
    padding: 0 30px;
    background: none;
    border-radius: 29px;
}

#pag-servico #busca .input-busca #input-procura, .pag-interna #busca .input-busca #input-procura {
    padding: 0 20px;
    padding-bottom: 2px;
}

#home.usuario-anonimo #busca .input-busca, #home.usuario-anonimo #busca .input-busca #input-procura {
    height: 70px;
    border-radius: 35px;
}

#home.usuario-anonimo #busca .input-busca #input-procura {
    font-size: 2.5em;
}

#busca .input-busca #input-procura::placeholder {
    color: #FFF;
}

#busca #btnProcura {
    position: absolute;
    background: none;
    border: none;
    font-size: 2.7em;
    color: #FFF;
    padding: 0;
    top: 15px;
    right: 19px;
}

#home.usuario-anonimo #busca #btnProcura {
    top: 15px;
    right: 25px;
    font-size: 3.3em;
}

#home.usuario-identificado #busca #btnProcura, #home.usuario-registrado #busca #btnProcura {
    color: #FFF;
}

#busca .list-mais-buscados {
    color: #00B958;
    font-size: 1.4em;
    margin-top: 10px;
    white-space: nowrap;
}

.usuario-identificado #busca .list-mais-buscados {
    color: #FFF;
}

#busca .list-mais-buscados a {
    color: #FFF;
    text-decoration: underline;
    opacity: .7;
}

    #busca .list-mais-buscados a:hover {
        opacity: 1;
    }

#busca #limparProcura {
    height: 35px;
    width: auto;
    border: 0;
    float: left;
    color: #00B858;
    position: absolute;
    top: 5px;
    right: 32px;
    background: none;
}

    #busca #limparProcura i.glyphicon {
        font-size: 1.5em;
    }

.busca-exemplo {
    color: #FFF;
    display: block;
    text-align: left;
    margin-top: 7px;
    font-size: 1.8em;
    margin-left: 63px;
}

#pag-servico .busca-exemplo, .pag-interna .busca-exemplo {
    font-size: 1.2em;
    margin-left: 23px;
}

body#home.usuario-anonimo #busca, body.usuario-identificado #busca, body.usuario-registrado #busca {
    padding: 24px 0;
}

body#home.usuario-anonimo #busca {
    text-align: center;
}

